argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -AssemblyName System.Windows.Forms
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class Win32Demo {
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
}
"@
$edge = Get-Process msedge -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne 0 } | Select-Object -First 1
if($null -eq $edge){ throw 'No visible Edge window' }
[Win32Demo]::ShowWindow($edge.MainWindowHandle,9) | Out-Null
[Win32Demo]::SetForegroundWindow($edge.MainWindowHandle) | Out-Null
Start-Sleep -Milliseconds 500
[System.Windows.Forms.SendKeys]::SendWait('^l')
[System.Windows.Forms.SendKeys]::SendWait('https://gemini.google.com/app')
[System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
Start-Sleep -Seconds 8
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$out=@()
for($i=0;$i -lt $all.Count;$i++){
  $e=$all.Item($i)
  $ct=$e.Current.ControlType.ProgrammaticName
  if($ct -match 'Edit|Button|Text|Document'){
    $name=[string]$e.Current.Name
    $aid=[string]$e.Current.AutomationId
    $cls=[string]$e.Current.ClassName
    if($name -or $aid){
      $r=$e.Current.BoundingRectangle
      $out += [pscustomobject]@{type=$ct;name=$name;automation_id=$aid;class=$cls;x=[int]$r.X;y=[int]$r.Y;w=[int]$r.Width;h=[int]$r.Height;focus=[bool]$e.Current.HasKeyboardFocus}
      if($out.Count -ge 120){break}
    }
  }
}
[pscustomobject]@{title=$edge.MainWindowTitle;controls=$out} | ConvertTo-Json -Depth 5 -Compress
